def grid_world(grouping):
    # Define valid movements
    movements = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # Initialize graph with states as nodes and edges as transitions
    graph = {i: [] for i in range(7)}

    # Populate the graph based on valid movements
    for state in range(7):
        if state != grouping["goal"] and "X" not in [grouping["grid"][j][i] for j, row in enumerate(grouping["grid"]) if i == state]:
            x = (state) % 3
            y = ((state - x) // 3)

            for dx, dy in movements:
                new_x = x + dx
                new_y = y + dy

                if 0 <= new_x < 3 and 0 <= new_y < 3:
                    new_state = new_y * 3 + new_x

                    if "X" not in [grouping["grid"][j][i] for j, row in enumerate(grouping["grid"]) if i == new_state]:
                        graph[state].append(new_state)

    return list(graph.keys()), graph

