                # Initialize the current state as an empty list and add it to the dictionary
                groups[(i, j)] = []

                # Perform DFS from the current state
                stack = [(i, j)]
                while stack:
                    x, y = stack.pop()

                    # If this state has been visited before, skip it
                    if (x, y) in groups:
