import networkx as nx

def group_states(grid):
    # Create a directed graph to represent the grid world
    G = nx.DiGraph()

    # Add states as nodes
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            node = (i, j)
            G.add_node(node)

    # Add edges between adjacent states
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] != 'X':  # Ignore obstacles ('X')
                node = (i, j)
                # Check all four directions
                if i > 0 and grid[i-1][j] != 'X':
                    G.add_edge(node, (i-1, j))
                if i < len(grid) - 1 and grid[i+1][j] != 'X':
                    G.add_edge(node, (i+1, j))
                if j > 0 and grid[i][j-1] != 'X':
                    G.add_edge(node, (i, j-1))
                if j < len(grid[i]) - 1 and grid[i][j+1] != 'X':
                    G.add_edge(node, (i, j+1))

    # Find connected components
    states = list(nx.connected_components(G))

    return [[list(state) for state in group] for group in states]

